INSERT INTO projects (project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES ('P054-04','CN0308','6万吨/年资源综合利用预处理装置升级','2026征求意见稿','2026-06-23','处理能力60000不变；贵金属预处理后产品225.81t/a，非催化剂产能','含碘盐水21000、含溴20190、含铯646.47t/a为产品量，不作废水量','S054-09');
INSERT INTO projects (project_id,site_id,project,status,date,capacity_note,water_change,source_id) VALUES ('P054-05','CN0304','稀贵金属新材料生产与技术研发项目','配套环保设施竣工公示','2026-08-14','非二期25t/a铂族金属回收项目','尚未得验收/调试及污水单元','S054-11');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-01','CN0306','S054-01','首次设计工艺','拟审批第4项目','1500t/a TMEDA，C区32#厂房，总投资2500、环保142万元均非污水专款。地洗/循环絮凝，工艺减压蒸馏/尾气吸收/真空/设备洗水蒸馏+炭吸附，蒸汽冷凝优先回用，剩余经调节池DW001间接排放；蒸馏残余及废炭危废。','WEB_PRIMARY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-02','CN0306','S054-02','产能与运行自述冲突','2026-07-28企业供稿','自述2000t/a、2025-06投产、2025出口500余吨；非独立证实。与1500设计及投资异文保留，不认作实际污水设施建成。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-03','CN0307','S054-03','生产用水循环与废物','2024-09-27清洁生产审核公示','纬一路3号、120t/a设计，称生产水全部循环无外排；喷淋循环装置及地面擦洗循环池污泥、结晶槽硝酸钾残渣等危废，原公示验收数据为废气非水。实际回用量及膜未识别。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-04','CN0307','S054-04','历史资源化及许可','公开转让说明书检索摘录','2010-05-12兰环建审[2010]048号500t/a项目，含硝酸铵废水经处理用于副产硝酸铵钙、生活化粪池排放。与2024硝酸钾残渣为不同时期陈述，不拼图。截图未定位具体页，正文检索摘录。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-05','CN0308','S054-05','共享站历史工艺','招股书1-1-191','500m³/d设计共享站，含酸中和MVR、含盐MVR、贵金属及无机碘化物反应洗涤过滤直接收集至共享站；部分回用、剩余运输至寿光华源。2021–2024H1排放量按报告录，非专线。截图超时。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-06','CN0308','S054-06','建设状态及许可','2025年报募集资金及资质章节','2025年100t/a贵金属及4100t/a有机碘溴子项目结项，60t/a发光项目终止，不把混合项目总投资当污水费。潍坊危证4号2025-12-24至2030-12-23，具体许可分项另核。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-07','CN0308','S054-08','审批及共享边界','募资说明第1页','2021-08-24潍环审字〔2021〕12号，100t/a贵金属项目，与其他产品共享处理；综合环保预估490万元非污水专款。部分贵金属滤液废液废盐鉴别后处置。截图404。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-08','CN0308','S054-09','预处理升级','2026-06-23公示','60000t/a资源预处理能力不变；产品盐水及贵金属预处理产出不当作废水量或催化剂净产量。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-09','CN0231','W07S07','污染源表及原表冲突','表4.3-5 p104、排放汇总p110截图','工艺、喷淋合计与原分项不相加；一期二期水量表2130.95m³/a、正文约6000t/a；COD工艺18.09t/a却组总16.27/16.275，不能重算原表或据此做成本；综合组10178.28m³/a、出水COD300/TN50设计，不是实测；制水反洗单独沉淀、生活化粪池。','WEB_PRIMARY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-10','CN0279','S054-10','正式设计批复','舟环岱建审〔2021〕17号第2/3条','石脑油2000、其余馏分/蜡油/渣油各6000t/a；含重金属设备清洗车间预处理，初雨混凝，经浙石化总排口纳基地站；生活单独纳含油单元。批复设计，不取代2023验收。截图失败。','WEB_PRIMARY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-11','CN0304','S054-11','项目阶段区分','2026-08-16竣工公示','稀贵金属新材料生产与技术研发项目配套环保设施2026-08-14竣工，非二期资源循环利用项目投产、验收。','WEB_SECONDARY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-12','CN0304','S054-12','历史经营','2026-09-04政府报道','企业已历史完成多类贵金属制备单元调试投产，2025累计投放近300种产品，非生产吨数；二期仍建设中。','WEB_PRIMARY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
INSERT INTO evidence_notes (note_id,site_id,source_id,topic,locator,detail,evidence_class,archive_status,created_on) VALUES ('N054-13','CN0028','S054-13','原件复核','2026半年报21页截图','复核旧新浪同报告COD60.6、氨氮3.12、TN9.08、TP0.197t；不重复入库。排口DW001与周村污水厂；PDF提取用字涂清、旧淦清，名称异文待核。','WEB_COMPANY','公开正文/截图/检索摘录，未归档原件','2026-11-28');
